ALTER TABLE schools MODIFY (MailStrAbr ANNOTATIONS (ADD value_description 'the abbreviated mailing street address of the school, district, or administrative authority.Note: Many active entities have not provided a mailing street address. For your convenience we have filled the unpopulated MailStrAbr cells with StreetAbr data.'));
ALTER TABLE schools MODIFY (MailCity ANNOTATIONS (ADD value_description 'The city associated with the mailing address of the school, district, or administrative authority. Note: Many entities have not provided a mailing address city. For your convenience we have filled the unpopulated MailCity cells with City data.'));
ALTER TABLE schools MODIFY (MailZip ANNOTATIONS (ADD value_description 'The zip code associated with the mailing address of the school, district, or administrative authority. Note: Many entities have not provided a mailing address zip code. For your convenience we have filled the unpopulated MailZip cells with Zip data.'));
ALTER TABLE schools MODIFY (MailState ANNOTATIONS (ADD value_description 'The state within the mailing address. For your convenience we have filled the unpopulated MailState cells with State data.'));
