COMMENT ON COLUMN schools.DOC IS 'District Ownership Code';
ALTER TABLE schools MODIFY (DOC ANNOTATIONS (ADD value_description 'The District Ownership Code (DOC) is the numeric code used to identify the category of the Administrative Authority.• 00 - County Office of Education• 02 – State Board of Education• 03 – Statewide Benefit Charter• 31 – State Special Schools• 34 – Non-school Location*• 52 – Elementary School District• 54 – Unified School District• 56 – High School District• 98 – Regional Occupational Center/Program (ROC/P)commonsense evidence:*Only the California Education Authority has been included in the non-school location category.'));
COMMENT ON COLUMN schools.DOCType IS 'The District Ownership Code Type is the text description of the DOC category.';
ALTER TABLE schools MODIFY (DOCType ANNOTATIONS (ADD value_description '(See text values in DOC field description above)'));
