ALTER TABLE schools MODIFY (EdOpsCode ANNOTATIONS (ADD value_description '• ALTSOC – Alternative School of Choice• COMM – County Community School• COMMDAY – Community Day School• CON – Continuation School• JUV – Juvenile Court School• OPP – Opportunity School• YTH – Youth Authority School• SSS – State Special School• SPEC – Special Education School• TRAD – Traditional• ROP – Regional Occupational Program• HOMHOS – Home and Hospital• SPECON – District Consortia Special Education School'));
COMMENT ON COLUMN schools.EdOpsName IS 'Educational Option Name';
